INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Who can play?', 'Only adults aged 18 and over. We check ID and never allow anyone under 18 to play.', 0),
  ('How do I become an agent?', 'Use the Become an Agent form. We review your location and documents, then guide you through training and setup.', 1),
  ('What if gambling is becoming a problem?', 'Talk to our staff about limits, breaks or self-exclusion, and reach out to someone you trust. Never chase losses.', 2),
  ('Are you licensed?', 'Our licence details are shown at the bottom of every page.', 3),
  ('Is the money on this website real?', 'Not while the site is in demo mode: balances, bets and games use fake money for illustration. Real betting happens only on our licensed platform.', 4),
  ('How are odds decided?', 'Odds reflect how likely each result is and can change before and during a match. The odds on your slip are confirmed when the bet is accepted.', 5);
